{ "explanation": "## Sine Wave Transformations: y = A sin(B(x − C)) + D

Each parameter shapes the wave:

- **A — Amplitude**: stretches the wave vertically. The peaks reach **A** and troughs reach **−A** (before D shifts things). Negative A flips the wave upside down.
- **B — Frequency**: compresses or stretches horizontally. The **period** becomes **2π/|B|** — bigger B means more waves fit in the same space.
- **C — Phase shift**: slides the whole wave left/right (positive C moves it right). Note it acts on *x − C*, so B only scales the wave's shape, not the shift.
- **D — Vertical shift**: moves the midline up or down to **y = D**.

Below, you get four live sliders to manipulate all parameters simultaneously, with the wave, a moving tracer dot, and dynamic readouts of the current period, amplitude, and midline.", "manimCode": "// Axes: symmetric y-range so the wave and midline stay centered
const ax = new Axes({
  xRange: [-2*Math.PI, 2*Math.PI, Math.PI/2],
  yRange: [-5, 5, 1],
  xLength: 10,
  yLength: 6,
  tips: true
});
const labels = ax.getAxisLabels();
scene.add(ax, labels);

// Parameters
let A = 1, B = 1, C = 0, D = 0;

const fn = (x) => A * Math.sin(B * (x - C)) + D;

// Curve (remove-recreate pattern for slider updates)
let curve = ax.plot(fn, { color: BLUE, xRange: [-2*Math.PI, 2*Math.PI], numSamples: 400 });
scene.add(curve);

// Midline at y = D
let midline = ax.plot(x => D, { color: GRAY, xRange: [-2*Math.PI, 2*Math.PI], strokeWidth: 2, strokeDasharray: [8, 6] });
scene.add(midline);

// Tracer dot that travels along the wave
const dot = new Dot({ point: ax.c2p(0, 0), color: YELLOW });
dot.addUpdater(() => {
  dot.moveTo(ax.c2p(0, fn(0)));
});
scene.add(dot);

// Current equation (recreated on every change)
let eq = new MathTex({ latex: 'y = 1\\sin(1(x - 0)) + 0', color: WHITE, fontSize: 32 });
await eq.waitForRender();
eq.moveTo([0, 3.4, 0]);
scene.add(eq);

// Info line: amplitude, period, midline
let info = new Text({ text: 'Amplitude: 1.0    Period: 6.28    Midline: y = 0.0', color: BLUE_B, fontSize: 22 });
info.moveTo([0, -3.4, 0]);
scene.add(info);

function rebuild() {
  // Rebuild curve
  scene.remove(curve);
  curve = ax.plot(fn, { color: BLUE, xRange: [-2*Math.PI, 2*Math.PI], numSamples: 400 });
  scene.add(curve);

  // Rebuild midline
  scene.remove(midline);
  midline = ax.plot(x => D, { color: GRAY, xRange: [-2*Math.PI, 2*Math.PI], strokeWidth: 2, strokeDasharray: [8, 6] });
  scene.add(midline);

  // Rebuild equation text
  const pos = eq.getCenter();
  scene.remove(eq);
  const aStr = (A >= 0 ? '' : '-') + String(Math.abs(A)).replace(/^(-?)0\./, '$1.');
  const cStr = (C >= 0 ? '-' : '+') + String(Math.abs(C)).replace(/^(-?)0\./, '$1.');
  const dSign = D >= 0 ? '+' : '-';
  const dStr = String(Math.abs(D)).replace(/^(-?)0\./, '$1.');
  eq = new MathTex({
    latex: 'y = ' + aStr + '\\sin\\big(' + String(B).replace(/^(-?)0\./, '$1.') + '(x ' + cStr + ')\\big) ' + dSign + ' ' + dStr,
    color: WHITE,
    fontSize: 32
  });
  eq.waitForRender().then(() => {
    eq.moveTo(pos);
    scene.add(eq);
  });

  // Rebuild info text
  const ipos = info.getCenter();
  scene.remove(info);
  const period = (2 * Math.PI / Math.abs(B)).toFixed(2);
  info = new Text({
    text: 'Amplitude: ' + Math.abs(A).toFixed(1) + '    Period: ' + period + '    Midline: y = ' + D.toFixed(1),
    color: BLUE_B,
    fontSize: 22
  });
  info.moveTo(ipos);
  scene.add(info);
}

// Controls
const controls = new Controls(scene, { position: 'top-right', width: 260 });

controls.addSlider({ label: 'A (amplitude)', min: -3, max: 3, value: 1, step: 0.1, onChange: (v) => { A = v; rebuild(); } });
controls.addSlider({ label: 'B (frequency)', min: 0.5, max: 4, value: 1, step: 0.1, onChange: (v) => { B = v; rebuild(); } });
controls.addSlider({ label: 'C (phase shift)', min: -3, max: 3, value: 0, step: 0.1, onChange: (v) => { C = v; rebuild(); } });
controls.addSlider({ label: 'D (vertical shift)', min: -3, max: 3, value: 0, step: 0.1, onChange: (v) => { D = v; rebuild(); } });

controls.addButton({
  label: 'Reset',
  onClick: () => {
    A = 1; B = 1; C = 0; D = 0;
    controls.setSliderValues({ 'A (amplitude)': 1, 'B (frequency)': 1, 'C (phase shift)': 0, 'D (vertical shift)': 0 });
    rebuild();
  }
});

// A draggable probe point: drag it to sample any point on the curve
const probe = new Dot({ point: ax.c2p(2, fn(2)), color: RED, radius: 0.12 });
let probeX = 2;
probe.addUpdater(() => {
  probe.moveTo(ax.c2p(probeX, fn(probeX)));
});
scene.add(probe);
makeDraggable(probe, scene, {
  constrainY: [-5, 5],
  onDrag: (mob) => {
    const wx = ax.p2c ? ax.p2c(mob.getCenter())[0] : null;
    // fallback: compute from world x
  }
});
probe.addUpdater(() => {
  const c = probe.getCenter();
  // convert world x back to axes x: axes span 10 units for 4*pi range centered
  probeX = (c[0] / 10) * (4 * Math.PI) ;
});

// Probe readout
let probeLabel = new Text({ text: '', color: RED_B, fontSize: 20 });
probeLabel.moveTo([-5.2, 2.9, 0]);
scene.add(probeLabel);
probeLabel.addUpdater(() => {
  const txt = 'x = ' + probeX.toFixed(2) + ',  y = ' + fn(probeX).toFixed(2);
  const pos = probeLabel.getCenter();
  scene.remove(probeLabel);
  probeLabel = new Text({ text: txt, color: RED_B, fontSize: 20 });
  probeLabel.moveTo(pos);
  scene.add(probeLabel);
});

await scene.wait(999999);" }

